/* Loads app data and enables offline app installation when served over HTTPS or localhost. */
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(error=>console.warn('Offline cache could not be enabled:',error));
const loadJson=async path=>{const response=await fetch(path);if(!response.ok)throw new Error('HTTP '+response.status+' · '+path);return response.json()};
const loadScript=src=>new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=()=>reject(new Error('Не удалось загрузить '+src));document.body.appendChild(script)});
(async()=>{try{const [map,data]=await Promise.all([loadJson('./data/legacy-map.json'),loadJson('./data/A1.json')]);window.OX3K_LEGACY_MAP=map.mapping;window.OX3K_LEVEL_COUNTS=map.levelCounts;window.OX3K_DATA={A1:data};await loadScript('./data/storage-core.js');await loadScript('./app.js')}catch(error){console.error(error);const panel=document.createElement('div');panel.className='empty';panel.textContent='Не удалось загрузить файлы тренажёра. Запусти start.bat из распакованной папки.';document.querySelector('main')?.prepend(panel)}})();
